var n=`1234-sancocho-dominicano`;var a=`world-1234`;var t=`DO`;var s=`central-america-caribbean`;var o=4;var r=157;var g={en:`Sancocho Dominicano`,ua:`Домініканське санкочо`};var l={en:`Sancocho Dominicano is a dish from Dominican Republic featuring beef chuck, pork shoulder, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Домініканське санкочо, страва кухні країни Домініканська Республіка з такими основними складниками: яловича лопатка, свиняча лопатка, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 105 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 105 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:105,i:[[`beef-chuck`,550,`g`],[`pork-shoulder`,480,`g`],[`water`,2e3,`ml`],[`yellow-onion`,150,`g`],[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 45 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 45 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:45,i:[[`chicken-thigh`,550,`g`],[`yam`,350,`g`],[`cassava-root`,400,`g`],[`plantain`,320,`g`],[`carrot`,240,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,30,`g`],[`lime`,1,`pcs`]]}];var m={slug:n,id:a,country:`DO`,region:s,servings:4,minutes:157,title:g,text:l,steps:c};export{t as country,m as default,a as id,r as minutes,s as region,o as servings,n as slug,c as steps,l as text,g as title};